"""--diff output."""

from aegisub_render.diff import text_lines, unified_diff


def test_comment_lines_take_no_part() -> None:
    old = ["[Script Info]", "; Script generated by Aegisub 3.5.0", "Title: x", "", "[Events]", "Dialogue: a"]
    new = [
        "[Script Info]",
        "; Script generated by Aegisub 3.5.0 with aegisub-render 0.1.0",
        "; https://aegisub.org/",
        "Title: x",
        "",
        "[Events]",
        "Comment: a",
        "Dialogue: b",
    ]
    assert unified_diff(old, new, "in.ass", "out.ass", context=1) == [
        "--- in.ass",
        "+++ out.ass",
        "@@ -5,2 +6,3 @@",  # line numbers in the whole files
        " [Events]",
        "-Dialogue: a",
        "+Comment: a",
        "+Dialogue: b",
    ]
    assert unified_diff(old, [*new[:6], "Dialogue: a"], "in.ass", "out.ass") == []


def test_pure_insertion() -> None:
    assert unified_diff(["a", "b"], ["a", "x", "b"], "1", "2", context=0) == ["--- 1", "+++ 2", "@@ -1,0 +2 @@", "+x"]


def test_text_lines() -> None:
    assert text_lines(b"\xef\xbb\xbfa\r\nb\nc\r") == ["a", "b", "c"]
    assert text_lines("﻿a\r\nb".encode("utf-16-le")) == ["a", "b"]
    assert text_lines(b"a\xffb") == ["a�b"]
    assert text_lines(b"") == []
